    {
        V = ProtocolInfo.Version,
        Type = MessageType.SHOT,
        Seq = seq,
        Coord = coordinate
    };

    public static ProtocolMessage Result(int seq, ShotOutcome outcome, ShipKind? ship = null) => new()
    {
        V = ProtocolInfo.Version,
