namespace Battleship.Server.Background;

public sealed class RoomReaper : BackgroundService
{
    private readonly RoomRegistry _registry;
    private readonly OptionsProvider _options;
    private readonly IpRateLimiter _ipLimiter;
    private readonly ILogger<RoomReaper> _logger;

    public RoomReaper(
        RoomRegistry registry,
        OptionsProvider options,
        IpRateLimiter ipLimiter,
        ILogger<RoomReaper> logger)
    {
        _registry = registry;
        _options = options;
        _ipLimiter = ipLimiter;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        var options = _options.Get();
        using var timer = new PeriodicTimer(TimeSpan.FromSeconds(options.ReaperIntervalSeconds));
        try
        {
            while (await timer.WaitForNextTickAsync(stoppingToken))
            {
                try
                {
                    await SweepAsync();
                }
                catch (Exception ex)
                {
                    _logger.LogError(ex, "room_reaper_failed");
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Host is stopping.
        }
    }

    private async Task SweepAsync()
    {
        var options = _options.Get();
        var now = DateTimeOffset.UtcNow;
        var idleTimeout = TimeSpan.FromSeconds(options.RoomIdleTimeoutSeconds);
        var maxLifetime = TimeSpan.FromMinutes(options.RoomMaxLifetimeMinutes);

        foreach (var room in _registry.Snapshot())
        {
            if (!room.IsExpired(now, idleTimeout, maxLifetime))
            {
                continue;
            }

            if (!room.TryMarkClosed())
            {
                continue;
            }

            var participants = room.SnapshotParticipants();
            foreach (var participant in participants)
            {
                participant.EnqueueClose(1001, "room expired");
            }

            if (_registry.TryRemove(room))
            {
                _logger.LogInformation("room_expired room={RoomCode}", room.Code);
                _logger.LogInformation("room_disposed room={RoomCode}", room.Code);
            }

            foreach (var participant in participants)
            {
                await participant.CompleteAsync(TimeSpan.FromSeconds(options.SendTimeoutSeconds));
            }
        }

        _ipLimiter.Cleanup(TimeSpan.FromMinutes(10));
    }
}

using Battleship.Server.Api;
using Battleship.Server.Background;
using Battleship.Server.Hosting;
using Battleship.Server.Options;
using Battleship.Server.RateLimiting;
using Battleship.Server.Realtime;
using Battleship.Server.Rooms;
using Battleship.Shared;
using Microsoft.AspNetCore.ResponseCompression;
using Microsoft.AspNetCore.StaticFiles;

var builder = WebApplication.CreateBuilder(args);

builder.Services
    .AddOptions<BattleshipOptions>()
    .Bind(builder.Configuration.GetSection(BattleshipOptions.SectionName));

builder.Services.AddResponseCompression(options =>
{
    options.EnableForHttps = true;
    options.MimeTypes = ResponseCompressionDefaults.MimeTypes.Concat(new[]
    {
        "application/wasm",
        "application/octet-stream"
    });
});

builder.Services.AddSingleton<OptionsProvider>();
builder.Services.AddSingleton<ProtocolCodec>();
builder.Services.AddSingleton<RoomRegistry>();
builder.Services.AddSingleton<RoomCodeGenerator>();
builder.Services.AddSingleton<IpRateLimiter>();
builder.Services.AddSingleton<MessageRelay>();
builder.Services.AddSingleton<RoomSocketHandler>();
builder.Services.AddSingleton<RoomApi>();
builder.Services.AddHostedService<RoomReaper>();

var app = builder.Build();
var startupOptions = app.Services.GetRequiredService<OptionsProvider>().Get();

app.UseMiddleware<SecurityHeadersMiddleware>();
app.UseResponseCompression();
app.UseWebSockets(new WebSocketOptions
{
    KeepAliveInterval = TimeSpan.FromSeconds(startupOptions.KeepAliveSeconds)
});

app.UseBlazorFrameworkFiles();
app.UseStaticFiles(new StaticFileOptions
{
    ContentTypeProvider = StaticContent.Types,
    OnPrepareResponse = StaticContent.Prepare
});

app.Use(async (context, next) =>
{
    if (context.Request.Path.StartsWithSegments("/api"))
    {
        context.Response.Headers["Cache-Control"] = "no-store";
        var options = context.RequestServices.GetRequiredService<OptionsProvider>().Get();
        var isCreate = HttpMethods.IsPost(context.Request.Method);
        var permits = isCreate
            ? options.CreateRoomPermitsPerMinute
            : options.ConnectPermitsPerMinute;
        var limiter = context.RequestServices.GetRequiredService<IpRateLimiter>();
        if (!limiter.TryAcquire(context, isCreate ? "create" : "connect", permits))
        {
            await HttpProblem.WriteAsync(
                context,
                StatusCodes.Status429TooManyRequests,
                "Too Many Requests",
                "The rate limit for this client IP has been exceeded.");
            return;
        }
    }

    await next();
});

app.MapPost("/api/rooms", (HttpContext context) =>
    app.Services.GetRequiredService<RoomApi>().CreateAsync(context));

app.MapGet("/api/rooms/{roomCode}", (HttpContext context) =>
{
    var roomCode = (string?)context.Request.RouteValues["roomCode"] ?? string.Empty;
    return app.Services.GetRequiredService<RoomApi>().GetAsync(context, roomCode);
});

app.MapGet("/ws/rooms/{roomCode}", (HttpContext context) =>
{
    var roomCode = (string?)context.Request.RouteValues["roomCode"] ?? string.Empty;
    return app.Services.GetRequiredService<RoomSocketHandler>().HandleAsync(context, roomCode);
});

app.MapMethods("/api/rooms", new[] { "PUT", "DELETE", "PATCH", "OPTIONS", "HEAD" }, (HttpContext context) =>
{
    context.Response.StatusCode = StatusCodes.Status405MethodNotAllowed;
    return Task.CompletedTask;
});

app.Lifetime.ApplicationStopping.Register(() =>
{
    var registry = app.Services.GetRequiredService<RoomRegistry>();
    foreach (var room in registry.Snapshot())
    {
        if (!room.TryMarkClosed())
        {
            continue;
        }

        var participants = room.SnapshotParticipants();
        foreach (var participant in participants)
        {
            participant.EnqueueClose(1001, "server shutting down");
        }

        registry.TryRemove(room);
        Task.WhenAll(participants.Select(participant => participant.CompleteAsync(TimeSpan.FromSeconds(1)))).Wait(TimeSpan.FromSeconds(2));
    }
});

app.MapFallback(async (HttpContext context) =>
{
    if (context.Request.Path.StartsWithSegments("/api")
        || context.Request.Path.StartsWithSegments("/ws"))
    {
        context.Response.StatusCode = StatusCodes.Status404NotFound;
        return;
    }

    await StaticContent.WriteIndexAsync(context, app.Environment);
});

app.Run();

using Battleship.Server.Rooms;
using Battleship.Shared;

namespace Battleship.Server.Realtime;

public sealed class MessageRelay
{
    private readonly ProtocolCodec _codec;
    private readonly ILogger<MessageRelay> _logger;

    public MessageRelay(ProtocolCodec codec, ILogger<MessageRelay> logger)
    {
        _codec = codec;
        _logger = logger;
    }

    public bool Relay(Room room, Participant sender, ProtocolMessage message)
    {
        if (message.V != ProtocolInfo.Version)
        {
            _logger.LogWarning(
                "message_rejected room={RoomCode} role={Role} reason=version",
                room.Code,
                sender.Role);
            sender.EnqueueText(_codec.Serialize(ProtocolMessage.Error(
                ProtocolErrorCode.VERSION_MISMATCH,
                "Protocol version mismatch. Reload the page.")));
            sender.EnqueueClose(1002, "version mismatch");
            return false;
        }

        var peer = room.PeerOf(sender);
        if (peer is null)
        {
            _logger.LogInformation(
                "message_rejected room={RoomCode} role={Role} reason=no_peer",
                room.Code,
                sender.Role);
            sender.EnqueueText(_codec.Serialize(ProtocolMessage.Error(
                ProtocolErrorCode.CONFLICT,
                "No opponent is connected.")));
            return true;
        }

        room.Touch();
        if (!peer.EnqueueText(_codec.Serialize(message)))
        {
            _logger.LogWarning(
                "message_rejected room={RoomCode} role={Role} reason=peer_unavailable",
                room.Code,
                sender.Role);
            sender.EnqueueText(_codec.Serialize(ProtocolMessage.Error(
                ProtocolErrorCode.FATAL,
                "The opponent connection is unavailable.")));
            return false;
        }

        _logger.LogInformation(
            "message_relayed room={RoomCode} type={Type} seq={Seq}",
            room.Code,
            message.Type,
            message.Seq);
        return true;
    }
}

using System.Net.WebSockets;
using Battleship.Server.Hosting;
using Battleship.Server.Options;
using Battleship.Server.RateLimiting;
using Battleship.Server.Rooms;
using Battleship.Shared;

namespace Battleship.Server.Realtime;

public sealed class RoomSocketHandler
{
    private readonly RoomRegistry _registry;
    private readonly OptionsProvider _options;
    private readonly IpRateLimiter _ipLimiter;
    private readonly MessageRelay _relay;
    private readonly ProtocolCodec _codec;
    private readonly ILogger<RoomSocketHandler> _logger;

    public RoomSocketHandler(
        RoomRegistry registry,
        OptionsProvider options,
        IpRateLimiter ipLimiter,
        MessageRelay relay,
        ProtocolCodec codec,
        ILogger<RoomSocketHandler> logger)
    {
        _registry = registry;
        _options = options;
        _ipLimiter = ipLimiter;
        _relay = relay;
        _codec = codec;
        _logger = logger;
    }

    public async Task HandleAsync(HttpContext context, string roomCode)
    {
        if (!context.WebSockets.IsWebSocketRequest)
        {
            await HttpProblem.WriteAsync(
                context,
                StatusCodes.Status400BadRequest,
                "Validation Failed",
                "A WebSocket upgrade request is required.");
            return;
        }

        var options = _options.Get();
        WebSocket socket;
        try
        {
            socket = await context.WebSockets.AcceptWebSocketAsync();
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "websocket_upgrade_failed");
            return;
        }

        var clientKey = IpRateLimiter.ClientKey(context);
        if (!_ipLimiter.TryAcquire("connect", clientKey, options.ConnectPermitsPerMinute))
        {
            _logger.LogWarning("rate_limited phase=connection ip={ClientIp}", clientKey);
            await CloseSocketAsync(socket, 4029, "connection rate limit exceeded", options.SendTimeoutSeconds);
            return;
        }

        var code = (roomCode ?? string.Empty).ToUpperInvariant();
        var roleText = context.Request.Query["role"].ToString().ToLowerInvariant();
        var isHost = roleText == "host";
        if (!ProtocolInfo.IsValidRoomCode(code) || (roleText != "host" && roleText != "client"))
        {
            await CloseSocketAsync(socket, 4400, "invalid room code or role", options.SendTimeoutSeconds);
            return;
        }

        var room = _registry.Get(code);
        if (room is null)
        {
            await CloseSocketAsync(socket, 4004, "room not found", options.SendTimeoutSeconds);
            return;
        }

        var role = isHost ? RoomRole.Host : RoomRole.Client;
        await using var participant = new Participant(
            socket,
            role,
            options.SendTimeoutSeconds,
            options.MessageBurst,
            options.MessagesPerSecond);

        var assignment = room.Assign(participant);
        switch (assignment)
        {
            case RoleAssignResult.Ok:
                break;
            case RoleAssignResult.HostNotConnected:
            case RoleAssignResult.RoomClosed:
                await CloseSocketAsync(socket, 4004, "room not found", options.SendTimeoutSeconds);
                return;
            default:
                _logger.LogInformation(
                    "room_full_rejected room={RoomCode} role={Role}",
                    room.Code,
                    role);
                await CloseSocketAsync(socket, 4009, "room slot is already taken", options.SendTimeoutSeconds);
                return;
        }

        _logger.LogInformation(
            "room_joined room={RoomCode} role={Role} participant={ParticipantId}",
            room.Code,
            role,
            participant.Id);

        participant.Start(_logger);
        try
        {
            await ReceiveLoopAsync(room, participant, context.RequestAborted);
        }
        catch (OperationCanceledException)
        {
            // The request was aborted.
        }
        catch (Exception ex)
        {
            _logger.LogWarning(ex, "socket_failed room={RoomCode} participant={ParticipantId}", room.Code, participant.Id);
            participant.EnqueueClose(1011, "internal error");
        }
        finally
        {
            await DisconnectAsync(room, participant, options);
        }
    }

    private async Task ReceiveLoopAsync(Room room, Participant participant, CancellationToken cancellationToken)
    {
        var buffer = new byte[ProtocolInfo.MaxMessageBytes + 1];
        using var messageBuffer = new MemoryStream(ProtocolInfo.MaxMessageBytes);

        while (participant.Socket.State == WebSocketState.Open && !cancellationToken.IsCancellationRequested)
        {
            WebSocketReceiveResult result;
            try
            {
                result = await participant.Socket.ReceiveAsync(
                    new ArraySegment<byte>(buffer),
                    cancellationToken);
            }
            catch (OperationCanceledException)
            {
                break;
            }
            catch (WebSocketException)
            {
                break;
            }
            catch (ObjectDisposedException)
            {
                break;
            }

            if (result.MessageType == WebSocketMessageType.Close)
            {
                break;
            }

            if (result.MessageType == WebSocketMessageType.Binary)
            {
                _logger.LogInformation("message_rejected room={RoomCode} reason=binary", room.Code);
                participant.EnqueueClose(1003, "binary frames are not supported");
                break;
            }

            if (messageBuffer.Length + result.Count > ProtocolInfo.MaxMessageBytes)
            {
                _logger.LogInformation("message_rejected room={RoomCode} reason=too_large", room.Code);
                participant.EnqueueClose(1009, "message too large");
                break;
            }

            messageBuffer.Write(buffer, 0, result.Count);
            if (!result.EndOfMessage)
            {
                continue;
            }

            var payload = messageBuffer.ToArray();
            messageBuffer.SetLength(0);

            if (!participant.TryConsumeMessage())
            {
                _logger.LogInformation(
                    "rate_limited room={RoomCode} participant={ParticipantId}",
                    room.Code,
                    participant.Id);
                participant.EnqueueText(_codec.Serialize(ProtocolMessage.Error(
                    ProtocolErrorCode.RATE_LIMITED,
                    "Too many messages; slow down.")));
                continue;
            }

            if (!_codec.TryDeserializeUtf8(payload, out var message, out var error) || message is null)
            {
                _logger.LogInformation(
                    "message_rejected room={RoomCode} participant={ParticipantId} reason=schema",
                    room.Code,
                    participant.Id);
                participant.EnqueueText(_codec.Serialize(ProtocolMessage.Error(
                    ProtocolErrorCode.VALIDATION,
                    error)));
                continue;
            }

            if (!_relay.Relay(room, participant, message))
            {
                break;
            }
        }
    }

    private async Task DisconnectAsync(Room room, Participant participant, BattleshipOptions options)
    {
        var (removed, peer) = room.Remove(participant);
        if (!removed)
        {
            return;
        }

        _logger.LogInformation(
            "participant_disconnected room={RoomCode} role={Role} participant={ParticipantId}",
            room.Code,
            participant.Role,
            participant.Id);

        await participant.CompleteAsync(TimeSpan.FromSeconds(options.SendTimeoutSeconds));

        if (peer is not null)
        {
            peer.EnqueueClose(4001, "peer disconnected");
        }

        if (room.TryCloseIfEmpty() && _registry.TryRemove(room))
        {
            _logger.LogInformation("room_disposed room={RoomCode}", room.Code);
        }
    }

    private static async Task CloseSocketAsync(WebSocket socket, int closeCode, string reason, int timeoutSeconds)
    {
        try
        {
            if (socket.State is WebSocketState.Open or WebSocketState.CloseReceived)
            {
                using var timeout = new CancellationTokenSource(TimeSpan.FromSeconds(Math.Max(1, timeoutSeconds)));
                await socket.CloseOutputAsync(
                    (WebSocketCloseStatus)closeCode,
                    reason,
                    timeout.Token);
            }
        }
        catch
        {
            // The client may already have gone away.
        }
        finally
        {
            socket.Dispose();
        }
    }
}

using System.Net.WebSockets;
using System.Text;
using System.Threading.Channels;
using Battleship.Server.RateLimiting;
using Battleship.Server.Realtime;

namespace Battleship.Server.Rooms;

public sealed class Participant : IAsyncDisposable
{
    private readonly Channel<Outbound> _queue =
        Channel.CreateUnbounded<Outbound>(new UnboundedChannelOptions
        {
            SingleReader = true,
            SingleWriter = false,
            AllowSynchronousContinuations = false
        });

    private readonly CancellationTokenSource _cts = new();
    private readonly int _sendTimeoutSeconds;
    private Task? _writer;
    private int _completed;

    public Participant(WebSocket socket, RoomRole role, int sendTimeoutSeconds, int messageBurst, int messagesPerSecond)
    {
        Socket = socket;
        Role = role;
        _sendTimeoutSeconds = Math.Max(1, sendTimeoutSeconds);
        Messages = new TokenBucket(messageBurst, messagesPerSecond);
    }

    public string Id { get; } = Guid.NewGuid().ToString("N");
    public WebSocket Socket { get; }
    public RoomRole Role { get; }
    public TokenBucket Messages { get; }

    public void Start(ILogger logger) => _writer ??= Task.Run(() => WriteLoopAsync(logger));

    public bool TryConsumeMessage() => Messages.TryTake();

    public bool EnqueueText(string json) =>
        Volatile.Read(ref _completed) == 0 && _queue.Writer.TryWrite(Outbound.Message(json));

    public bool EnqueueClose(int closeCode, string? reason) =>
        _queue.Writer.TryWrite(Outbound.Close(closeCode, reason));

    public async Task CompleteAsync(TimeSpan timeout)
    {
        if (Interlocked.Exchange(ref _completed, 1) == 1)
        {
            return;
        }

        _queue.Writer.TryComplete();
        if (_writer is not null)
        {
            try
            {
                await _writer.WaitAsync(timeout);
            }
            catch (TimeoutException)
            {
                _cts.Cancel();
                try
                {
                    await _writer;
                }
                catch
                {
                    // The writer is stopped; nothing else to flush.
                }
            }
            catch
            {
                // A failed writer has already aborted the socket.
            }
        }

        try
        {
            if (Socket.State is WebSocketState.Open or WebSocketState.CloseReceived)
            {
                await Socket.CloseOutputAsync(WebSocketCloseStatus.NormalClosure, null, CancellationToken.None);
            }
        }
        catch
        {
            // The peer may already be gone.
        }

        Socket.Dispose();
        _cts.Dispose();
    }

    public async ValueTask DisposeAsync() =>
        await CompleteAsync(TimeSpan.FromSeconds(_sendTimeoutSeconds + 1));

    private async Task WriteLoopAsync(ILogger logger)
    {
        try
        {
            await foreach (var item in _queue.Reader.ReadAllAsync(_cts.Token))
            {
                using var timeout = CancellationTokenSource.CreateLinkedTokenSource(_cts.Token);
                timeout.CancelAfter(TimeSpan.FromSeconds(_sendTimeoutSeconds));
                try
                {
                    if (item.CloseCode is not null)
                    {
                        if (Socket.State is WebSocketState.Open or WebSocketState.CloseReceived)
                        {
                            await Socket.CloseOutputAsync(
                                (WebSocketCloseStatus)item.CloseCode.Value,
                                item.Reason,
                                timeout.Token);
                        }

                        break;
                    }

                    if (Socket.State != WebSocketState.Open)
                    {
                        break;
                    }

                    var bytes = Encoding.UTF8.GetBytes(item.Text!);
                    await Socket.SendAsync(
                        new ArraySegment<byte>(bytes),
                        WebSocketMessageType.Text,
                        endOfMessage: true,
                        timeout.Token);
                }
                catch (OperationCanceledException)
                {
                    Socket.Abort();
                    break;
                }
                catch (WebSocketException)
                {
                    Socket.Abort();
                    break;
                }
                catch (ObjectDisposedException)
                {
                    break;
                }
            }
        }
        catch (OperationCanceledException)
        {
            // Shutdown.
        }
        catch (Exception ex)
        {
            logger.LogWarning(ex, "participant_writer_failed participant={ParticipantId}", Id);
            Socket.Abort();
        }
    }
}

using Battleship.Server.Realtime;

namespace Battleship.Server.Rooms;

public enum RoomRole
{
    Host,
    Client
}

public enum RoleAssignResult
{
    Ok,
    HostSlotTaken,
    ClientSlotTaken,
    HostNotConnected,
    RoomClosed
}

public sealed class Room
{
    private readonly object _sync = new();
    private DateTimeOffset _lastActivity;
    private bool _hostAssigned;

    public Room(string code, DateTimeOffset createdAt)
    {
        Code = code;
        CreatedAt = createdAt;
        _lastActivity = createdAt;
    }

    public string Code { get; }
    public DateTimeOffset CreatedAt { get; }
    public Participant? Host { get; private set; }
    public Participant? Client { get; private set; }
    public bool IsClosed { get; private set; }

    public int ParticipantCount
    {
        get
        {
            lock (_sync)
            {
                return CountCore;
            }
        }
    }

    public DateTimeOffset LastActivity
    {
        get
        {
            lock (_sync)
            {
                return _lastActivity;
            }
        }
    }

    public RoleAssignResult Assign(Participant participant)
    {
        lock (_sync)
        {
            if (IsClosed)
            {
                return RoleAssignResult.RoomClosed;
            }

            if (participant.Role == RoomRole.Host)
            {
                if (Host is not null || _hostAssigned)
                {
                    return RoleAssignResult.HostSlotTaken;
                }

                Host = participant;
                _hostAssigned = true;
            }
            else
            {
                if (Client is not null)
                {
                    return RoleAssignResult.ClientSlotTaken;
                }

                if (Host is null)
                {
                    return RoleAssignResult.HostNotConnected;
                }

                Client = participant;
            }

            _lastActivity = DateTimeOffset.UtcNow;
            return RoleAssignResult.Ok;
        }
    }

    public Participant? PeerOf(Participant participant)
    {
        lock (_sync)
        {
            if (Host is not null && Host.Id == participant.Id)
            {
                return Client;
            }

            if (Client is not null && Client.Id == participant.Id)
            {
                return Host;
            }

            return null;
        }
    }

    public (bool Removed, Participant? Peer) Remove(Participant participant)
    {
        lock (_sync)
        {
            var removed = false;
            if (Host is not null && Host.Id == participant.Id)
            {
                Host = null;
                removed = true;
            }
            else if (Client is not null && Client.Id == participant.Id)
            {
                Client = null;
                removed = true;
            }

            if (!removed)
            {
                return (false, null);
            }

            _lastActivity = DateTimeOffset.UtcNow;
            return (true, Host ?? Client);
        }
    }

    public void Touch()
    {
        lock (_sync)
        {
            _lastActivity = DateTimeOffset.UtcNow;
        }
    }

    public bool TryCloseIfEmpty()
    {
        lock (_sync)
        {
            if (IsClosed || CountCore != 0)
            {
                return false;
            }

            IsClosed = true;
            _lastActivity = DateTimeOffset.UtcNow;
            return true;
        }
    }

    public bool TryMarkClosed()
    {
        lock (_sync)
        {
            if (IsClosed)
            {
                return false;
            }

            IsClosed = true;
            _lastActivity = DateTimeOffset.UtcNow;
            return true;
        }
    }

    public bool IsExpired(DateTimeOffset now, TimeSpan idleTimeout, TimeSpan maxLifetime)
    {
        lock (_sync)
        {
            if (IsClosed)
            {
                return false;
            }

            if (CountCore == 0 && now - _lastActivity >= idleTimeout)
            {
                return true;
            }

            return now - CreatedAt >= maxLifetime;
        }
    }

    public Participant[] SnapshotParticipants()
    {
        lock (_sync)
        {
            return new[] { Host, Client }.Where(p => p is not null).Cast<Participant>().ToArray();
        }
    }

    private int CountCore => (Host is not null ? 1 : 0) + (Client is not null ? 1 : 0);
}

using System.Collections.Concurrent;

namespace Battleship.Server.Rooms;

public sealed class RoomRegistry
{
    private readonly ConcurrentDictionary<string, Room> _rooms = new(StringComparer.Ordinal);

    public int Count => _rooms.Count;

    public bool TryAdd(Room room) => _rooms.TryAdd(room.Code, room);

    public Room? Get(string code) => _rooms.TryGetValue(code, out var room) ? room : null;

    public Room[] Snapshot() => _rooms.Values.ToArray();

    public bool TryRemove(Room room) =>
        ((ICollection<KeyValuePair<string, Room>>)_rooms)
        .Remove(new KeyValuePair<string, Room>(room.Code, room));
}

